formula:
AVERAGE(
  FILTER(
    INDEX(
      Table_SalesData_AmericanPizza,,
      MATCH(HN, INDEX(Table_SalesData_AmericanPizza,1,),0)
    ),

    ARRAYFORMULA(
      PERSIAN_WEEKDAY(
        INDEX(Table_SalesData_AmericanPizza,,1)
      )
    ) = PERSIAN_WEEKDAY(HN),

    ARRAYFORMULA(
      PERSIAN_TO_GREGORIAN(
        INDEX(Table_SalesData_AmericanPizza,,1)
      )
    ) >= PERSIAN_TO_GREGORIAN(HN)-30,

    ARRAYFORMULA(
      PERSIAN_TO_GREGORIAN(
        INDEX(Table_SalesData_AmericanPizza,,1)
      )
    ) <= PERSIAN_TO_GREGORIAN(HN)
  )
)

AVERAGE(
  FILTER(
    INDEX(Table_SalesData_AmericanPizza,,2),

    ARRAYFORMULA(
      PERSIAN_WEEKDAY(
        INDEX(Table_SalesData_AmericanPizza,,1)
      )
    ) = PERSIAN_WEEKDAY(HN),

    ARRAYFORMULA(
      PERSIAN_TO_GREGORIAN(
        INDEX(Table_SalesData_AmericanPizza,,1)
      )
    ) >= PERSIAN_TO_GREGORIAN(HN)-30,

    ARRAYFORMULA(
      PERSIAN_TO_GREGORIAN(
        INDEX(Table_SalesData_AmericanPizza,,1)
      )
    ) <= PERSIAN_TO_GREGORIAN(HN)
  )
)

AVERAGE(
  FILTER(
    Table_SalesData_AmericanPizza,

      PERSIAN_WEEKDAY(
        INDEX(Table_SalesData_AmericanPizza,,1)
      )
    = PERSIAN_WEEKDAY(TEXT(HN))
  )
)
